SELECT COUNT(1)
FROM notification_answer
WHERE notification_id = #{notificationId}
  AND question_id = #{questionId}
  AND student_id = #{studentId}

SELECT answer_id, notification_id, question_id, answer_data, user_id, student_id, create_time
FROM notification_answer
WHERE notification_id = #{notificationId}
  AND student_id = #{studentId}
ORDER BY question_id, answer_id
